import itertools
from collections import deque

def get_all_2x2_subgrids(N):
    subgrids = []
    for i in range(N - 1):
        for j in range(N - 1):
            subgrids.append([(i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)])
    return subgrids

def apply_rule1(grid, subgrid):
    # Rule 1: If exactly 3 are 1, make all 4 as 1.
    sum_val = sum(grid[r][c] for r, c in subgrid)
    if sum_val == 3:
        new_grid = [row[:] for row in grid]
        for r, c in subgrid:
            new_grid[r][c] = 1
        return new_grid
    return None

def apply_rule2(grid, subgrid):
    # Rule 2: If exactly 2 are 1, flip all 4.
    sum_val = sum(grid[r][c] for r, c in subgrid)
    if sum_val == 2:
        new_grid = [row[:] for row in grid]
        for r, c in subgrid:
            new_grid[r][c] = 1 - new_grid[r][c]
        return new_grid
    return None

def grid_to_tuple(grid):
    return tuple(tuple(row) for row in grid)

def solve_for_k(N, k):
    # For a given N and k, check if all configurations of k infected cells can reach full infection.
    # This is too slow for N=4, but maybe for N=2, 3.
    import itertools

    cells = [(i, j) for i in range(N) for j in range(N)]
    subgrids = get_all_2x2_subgrids(N)

    for start_cells in itertools.combinations(cells, k):
        # Initial grid
        grid = [[0]*N for _ in range(N)]
        for r, c in start_cells:
            grid[r][c] = 1

        # BFS to see if all 1s can be reached
        visited = {grid_to_tuple(grid)}
        queue = deque([grid])
        reached_full = False

        while queue:
            curr_grid = queue.popleft()
            if all(all(cell == 1 for cell in row) for row in curr_grid):
                reached_full = True
                break

            # Try all possible 2x2 operations
            for subgrid in subgrids:
                # Try Rule 1
                next_grid = apply_rule1(curr_grid, subgrid)
                if next_grid:
                    t = grid_to_tuple(next_grid)
                    if t not in visited:
                        visited.add(t)
                        queue.append(next_grid)

                # Try Rule 2
                next_grid = apply_rule2(curr_grid, subgrid)
                if next_grid:
                    t = grid_to_tuple(next_grid)
                    if t not in visited:
                        visited.add(t)
                        queue.append(next_grid)

        if not reached_full:
            return False
    return True

for N in [2, 3]:
    for k in range(N*N + 1):
        if solve_for_k(N, k):
            print(f"N={N}, min k = {k}")
            break

# Re-running solve_for_k for N=3 more carefully
for k in range(1, 10):
    if solve_for_k(3, k):
        print(f"N=3, k={k} works")
    else:
        print(f"N=3, k={k} fails")

